(()=>{window.__qaRead=null;(async()=>{try{
const ls=localStorage.getItem('xray:qa-sentinel');
const row=await new Promise((resolve)=>{const r=indexedDB.open('xray-qa-sentinel',1);
  r.onupgradeneeded=()=>r.result.createObjectStore('s',{keyPath:'k'});
  r.onsuccess=()=>{const db=r.result;
    if(!db.objectStoreNames.contains('s')){db.close();resolve(null);return}
    const q=db.transaction('s').objectStore('s').get('sentinel');
    q.onsuccess=()=>{db.close();resolve(q.result||null)};q.onerror=()=>{db.close();resolve(null)}};
  r.onerror=()=>resolve(null)});
window.__qaRead={localStorageSentinel:ls,indexedDbSentinel:row?row.v:null,
survivedLocalStorage:ls==='written-by-18a',survivedIndexedDb:!!row&&row.v==='written-by-18a',
totalKeys:Object.keys(localStorage).length};
}catch(e){window.__qaRead={error:String(e)}}})();return 'reading sentinels'})()
